from pathlib import Path
import subprocess,json,re
O=Path(__file__).parent;chrome=O.parents[1]/'video/node_modules/.remotion/chrome-headless-shell/win64/chrome-headless-shell-win64/chrome-headless-shell.exe'
test='''<script>let timer=setInterval(()=>{if(!window.ATLAS)return;clearInterval(timer);let out={count:ATLAS.data.items.length,loaded:!document.getElementById('loading'),search:false,detail:false,region:false,wheel:false,drag:false,capture:false};try{let e=document.getElementById('search');e.value='반포자이';e.dispatchEvent(new Event('input'));let row=document.querySelector('[data-i]');out.search=!!row;row.click();out.detail=document.getElementById('title').textContent.includes('반포자이')&&document.getElementById('details').textContent.includes('116501');e.value='';let r=document.getElementById('region');r.value='28';r.dispatchEvent(new Event('change'));out.region=[...document.querySelectorAll('.result small')].every(x=>x.textContent.startsWith('인천'));let c=document.getElementById('map'),before=ATLAS.getView();c.dispatchEvent(new WheelEvent('wheel',{clientX:700,clientY:400,deltaY:-100,cancelable:true}));out.wheel=ATLAS.getView().s>before.s;before=ATLAS.getView();c.onpointerdown({clientX:700,clientY:400,pointerId:1});c.onpointermove({clientX:720,clientY:410});out.drag=ATLAS.getView().x!==before.x;c.onpointerup({clientX:720,clientY:410});document.getElementById('capture').click();out.capture=document.body.classList.contains('capture');document.getElementById('capture').click();document.getElementById('reset').click()}catch(e){out.error=e.message}let p=document.createElement('pre');p.id='qa_result';p.textContent=JSON.stringify(out);document.body.append(p)},100)</script>'''
# pointer capture requires real pointer; replace direct call with safe dispatch-independent drag test.
test=test.replace("c.onpointerdown({clientX:700,clientY:400,pointerId:1});","c.setPointerCapture=()=>{};c.onpointerdown({clientX:700,clientY:400,pointerId:1});")
file=O/'qa_runtime.html';file.write_text((O/'index.html').read_text(encoding='utf8').replace('</html>',test+'</html>'),encoding='utf8')
r=subprocess.run([str(chrome),'--headless','--no-sandbox','--disable-gpu','--dump-dom','--window-size=1440,1000','--virtual-time-budget=15000',file.as_uri()],capture_output=True,timeout=50)
s=r.stdout.decode('utf8',errors='replace');m=re.search(r'<pre id="qa_result">(.*?)</pre>',s,re.S);result=json.loads(m[1]) if m else {'failure':'runtime result missing','stderr':r.stderr.decode('utf8',errors='replace')[-1000:]};(O/'ui_validation.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf8');file.unlink();print(json.dumps(result,ensure_ascii=False,indent=2));assert all(result.get(k) for k in ['loaded','search','detail','region','wheel','drag','capture'])
